202:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
203:     if (dot < -0.25) return;
204:     const score = dist + (dot < 0.15 ? 0.55 : 0);
205:     if (score < bestScore) { best = { obj, type, dist }; bestScore = score; }
206:   };
207:   for (const npc of npcs) if (npc.alive && npc.state !== 'grabbed') consider(npc, npc.group.position, 'npc');
