195: function nearestTarget(maxDist = 1.65) {
196:   const p = player.group.position;
197:   let best = null, bestScore = Infinity;
198:   const consider = (obj, point, type) => {
199:     const dx = point.x - p.x, dz = point.z - p.z;
200:     const dist = Math.hypot(dx, dz);
201:     if (dist > maxDist) return;
202:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
203:     if (dot < -0.25) return;
204:     const score = dist + (dot < 0.15 ? 0.55 : 0);
205:     if (score < bestScore) { best = { obj, type, dist }; bestScore = score; }
206:   };
207:   for (const npc of npcs) if (npc.alive && npc.state !== 'grabbed') consider(npc, npc.group.position, 'npc');
208:   for (const weapon of weapons) if (weapon.state === 'ground') consider(weapon, weapon.group.position, 'weapon');
209:   return best;
210: }
