function spawnNPC(force = false) {
  if (!player.alive || npcs.filter(n => n.alive).length >= QUALITY.maxNPCs) return;
  const angle = Math.random() * Math.PI * 2;
  const radius = Math.max(1.35, currentMap.bounds * .68) + Math.random() * .45;
