215:     const dist = Math.hypot(dx, dz);
216:     if (dist > maxDist) return;
217:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
218:     if (dot < -0.25) return;
219:     const score = dist + (dot < 0.15 ? 0.55 : 0);
220:     if (score < bestScore) { best = { obj, type, dist }; bestScore = score; }
221:   };
222:   for (const npc of npcs) if (npc.alive && npc.state !== 'grabbed') consider(npc, npc.group.position, 'npc');
223:   for (const weapon of weapons) if (weapon.state === 'ground') consider(weapon, weapon.group.position, 'weapon');
224:   return best;
225: }
