42:     this.stats = VARIANTS[this.variant];
43:     this.maxHealth = this.stats.maxHealth;
44:     this.health = this.maxHealth;
45:     this.state = 'chase';
46:     this.attackCooldown = rand(...this.stats.cooldown);
47:     this.attackWindup = 0;
48:     this.staggerT = 0;
49:     this.deathT = 0;
