51:     this.walkPhase = rand(0, 10);
52:     this.flash = 0;
53:     this.vel = new THREE.Vector3();
54:     this.spin = new THREE.Vector3();
55:     this.hitCount = 0;
56:     this.throwT = 0;
57:     this.grabT = 0;
58:     this.baseScale = opts.scale ?? 1;
59:     this.visualScale = this.stats.visualScale;
60:     this.bounds = Number.isFinite(opts.bounds) ? Math.max(0, opts.bounds) : 1.66;
