75:   build() {
76:     const M = (color, opts = {}) => {
77:       const m = lit(color, opts);
78:       this.materials.push(m);
79:       return m;
80:     };
81:     this.materials = [];
82:     this.root.scale.setScalar(this.visualScale);
83:     const skin = M(this.stats.skin);
84:     const skinDark = M(this.stats.skinDark);
85:     const shorts = M(0x24201f, { roughness: 0.9 });
86:     const bone = M(0xd8ccb0, { roughness: 0.55 });
87:     const blood = M(0x4d0b0e, { roughness: 0.4 });
88:     const bloodBright = M(0x7d1116, { roughness: 0.38 });
89:     const eye = M(0xff2b18, { emissive: 0xff1a0a, emissiveIntensity: 2.4, roughness: 0.3 });
90:     const mouth = M(0x1a0a0b, { roughness: 0.8 });
91: 
92:     const add = (parent, geo, mat, x, y, z) => {
93:       const m = new THREE.Mesh(geo, mat);
94:       m.position.set(x, y, z);
95:       m.castShadow = false;
96:       m.receiveShadow = false;
97:       parent.add(m);
98:       return m;
99:     };
100: 
101:     // torso + hips
102:     const hips = add(this.root, new THREE.BoxGeometry(0.3, 0.2, 0.22), shorts, 0, 0.72, 0);
103:     hips.geometry.translate(0, 0, 0);
104:     hips.scale.set(this.stats.bodyWidth, 1, this.stats.bodyDepth);
105:     const torso = add(this.root, new THREE.CapsuleGeometry(0.185, 0.34, 2, 5), skin, 0, 1.04, 0);
106:     torso.scale.set(1.1 * this.stats.bodyWidth, 1, 0.72 * this.stats.bodyDepth);
107:     if (this.variant === 'bloated') {
108:       const belly = add(this.root, new THREE.SphereGeometry(0.19, 8, 6), skin, 0, 0.94, 0.105);
109:       belly.scale.set(1.45, 1.05, 0.8);
110:     }
111: 
112:     // exposed rib cage (gore)
113:     const wound = add(this.root, new THREE.SphereGeometry(0.13, 7, 5), bloodBright, 0, 1.08, 0.135);
114:     wound.scale.set(1.25, 1.35, 0.32);
115:     for (let i = 0; i < 2; i++) {
116:       const rib = add(this.root, new THREE.BoxGeometry(0.19 - i * 0.025, 0.017, 0.02), bone, 0, 1.15 - i * 0.07, 0.163);
117:       rib.rotation.z = (i % 2 ? 1 : -1) * 0.12;
118:     }
119:     // splatter patches
120:     for (let i = 0; i < 3; i++) {
121:       const p = add(this.root, new THREE.SphereGeometry(rand(0.02, 0.05), 7, 5), i % 2 ? blood : bloodBright,
122:         rand(-0.16, 0.16), rand(0.75, 1.3), rand(0.1, 0.15));
123:       p.scale.set(rand(0.7, 1.6), rand(0.7, 1.5), 0.28);
124:     }
125: 
126:     // head
127:     const headGroup = new THREE.Group();
128:     headGroup.position.set(0, 1.47, 0.01);
129:     this.root.add(headGroup);
130:     this.head = headGroup;
131:     const skull = add(headGroup, new THREE.SphereGeometry(0.155, 8, 6), skin, 0, 0, 0);
132:     skull.scale.set(0.94, 1.06, 0.96);
133:     add(headGroup, new THREE.BoxGeometry(0.2, 0.07, 0.11), skinDark, 0, 0.055, 0.09);
134:     add(headGroup, new THREE.BoxGeometry(0.13, 0.05, 0.09), mouth, 0, -0.075, 0.125);
135:     for (let i = 0; i < 4; i++) {
136:       add(headGroup, new THREE.BoxGeometry(0.018, 0.03, 0.02), bone, -0.045 + i * 0.03, -0.062, 0.16);
137:     }
138:     for (const side of [-1, 1]) {
139:       const e = add(headGroup, new THREE.SphereGeometry(0.024, 8, 6), eye, side * 0.06, 0.02, 0.135);
140:       e.scale.set(1.2, 0.7, 0.6);
141:     }
142:     // head wounds
143:     for (let i = 0; i < 1; i++) {
144:       const p = add(headGroup, new THREE.SphereGeometry(rand(0.025, 0.045), 5, 4), blood, rand(-0.1, 0.1), rand(0.02, 0.11), rand(0.1, 0.14));
145:       p.scale.set(1, 0.6, 0.25);
146:     }
147: 
148:     // arms
149:     const makeArm = (side) => {
150:       const pivot = new THREE.Group();
151:       pivot.position.set(side * 0.27, 1.22, 0);
152:       this.root.add(pivot);
153:       const upper = add(pivot, new THREE.CapsuleGeometry(0.055, 0.2, 2, 4), skin, 0, -0.14, 0);
154:       upper.scale.set(1, 1, 0.9);
155:       const fore = add(pivot, new THREE.CapsuleGeometry(0.05, 0.19, 2, 4), skinDark, 0, -0.38, 0);
156:       fore.rotation.z = side * 0.05;
157:       const hand = add(pivot, new THREE.SphereGeometry(0.068, 6, 4), bloodBright, 0, -0.53, 0.02);
158:       hand.scale.set(0.85, 1, 0.9);
159:       // arm blood
160:       const smear = add(pivot, new THREE.SphereGeometry(0.04, 6, 5), blood, side * 0.03, -0.26, 0.02);
161:       smear.scale.set(0.8, 1.7, 0.25);
162:       return pivot;
163:     };
164:     this.armL = makeArm(-1);
165:     this.armR = makeArm(1);
166: 
167:     // legs
168:     const makeLeg = (side) => {
169:       const pivot = new THREE.Group();
170:       pivot.position.set(side * 0.11, 0.68, 0);
171:       this.root.add(pivot);
172:       add(pivot, new THREE.CapsuleGeometry(0.07, 0.22, 2, 4), skinDark, 0, -0.16, 0);
173:       add(pivot, new THREE.CapsuleGeometry(0.058, 0.2, 2, 4), skin, 0, -0.42, 0);
174:       add(pivot, new THREE.BoxGeometry(0.11, 0.07, 0.2), shorts, 0, -0.6, 0.035);
175:       return pivot;
176:     };
177:     this.legL = makeLeg(-1);
178:     this.legR = makeLeg(1);
