183:   buildBar() {
184:     const g = new THREE.Group();
185:     const back = new THREE.Mesh(new THREE.PlaneGeometry(0.56, 0.085), new THREE.MeshBasicMaterial({ color: 0x08080a, transparent: true, opacity: 0.72, depthWrite: false }));
186:     const fill = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 0.045), new THREE.MeshBasicMaterial({ color: 0xd41f28, depthWrite: false }));
187:     fill.position.z = 0.002;
188:     g.add(back, fill);
189:     g.position.y = 1.86;
190:     g.visible = false;
191:     this.scene.add(g);
