195: 
196:   get position() { return this.group.position; }
197:   get alive() { return this.state !== 'dead'; }
198: 
199:   setGrabbed(player) {
200:     if (this.state !== 'grabbed') {
201:       this.state = 'grabbed';
202:       this.grabT = 0;
203:       this.attackWindup = 0;
204:       this.vel.set(0, 0, 0);
205:       this.root.rotation.set(0, 0, 0);
206:     }
207:     this.grabT += 1 / 60;
208:     const p = player.group.position;
209:     const f = player.forward;
210:     this.group.position.set(
211:       p.x + f.x * 0.62,
212:       1.06 + Math.sin(this.grabT * 9) * 0.025,
213:       p.z + f.z * 0.62
214:     );
215:     this.group.rotation.y = player.facingYaw;
216:     this.root.rotation.z = Math.sin(this.grabT * 7) * 0.16;
217:     this.root.rotation.x = -0.14 + Math.sin(this.grabT * 5) * 0.08;
218:   }
219: 
220:   release() {
221:     if (this.state === 'grabbed') {
222:       this.state = 'stagger';
223:       this.staggerT = 0.22;
224:       this.root.rotation.set(0, 0, 0);
225:       this.group.position.y = 0;
226:       this.vel.set(0, 0, 0);
227:     }
228:   }
229: 
230:   throwIt(dir) {
231:     this.state = 'thrown';
232:     this.throwT = 0;
233:     this.root.rotation.set(0, 0, 0);
234:     this.group.position.y = 1.0;
235:     this.vel.set(dir.x * 6.4, 3.6, dir.z * 6.4);
236:     this.spin.set(rand(-9, 9), rand(-5, 5), rand(-9, 9));
237:     this.attackWindup = 0;
238:   }
