240:   update(dt, game) {
241:     if (this.removed) return;
242:     const player = game.player;
243: 
244:     // flash decay
245:     if (this.flash > 0) {
246:       this.flash -= dt;
247:       const e = clamp(this.flash / 0.12, 0, 1);
248:       for (const m of this.materials) {
249:         m.emissive.setRGB(e * 0.9, e * 0.06, e * 0.03);
250:       }
251:     }
252: 
253:     // health bar
254:     const alive = this.alive;
255:     const distToPlayer = Math.hypot(this.group.position.x - player.group.position.x, this.group.position.z - player.group.position.z);
256:     this.bar.visible = alive && (this.health < this.maxHealth || distToPlayer < 3.2) && this.state !== 'grabbed';
257:     if (this.bar.visible) {
258:       this.bar.position.set(this.group.position.x, this.group.position.y + 1.86 * this.baseScale * this.visualScale, this.group.position.z);
259:       this.bar.quaternion.copy(game.camera.quaternion);
260:       const ratio = clamp(this.health / this.maxHealth, 0, 1);
261:       this.barFill.scale.x = Math.max(0.001, ratio);
262:       this.barFill.position.x = -(1 - ratio) * 0.25;
263:     }
264: 
265:     if (this.state === 'dead') {
266:       this.updateDeath(dt);
267:       return;
268:     }
269: 
270:     if (this.state === 'grabbed') {
271:       this.animateGrabbed(dt);
272:       return;
273:     }
274: 
275:     if (this.state === 'thrown') {
276:       this.updateThrown(dt, game);
277:       return;
278:     }
279: 
280:     if (this.state === 'stagger') {
281:       this.staggerT -= dt;
282:       this.group.position.x += this.vel.x * dt;
283:       this.group.position.z += this.vel.z * dt;
284:       this.vel.multiplyScalar(Math.max(0, 1 - dt * 7));
285:       this.root.rotation.x = lerp(this.root.rotation.x, 0.25, dt * 10);
286:       this.group.position.y = 0;
287:       this.animateWalk(dt, 0.4);
288:       if (this.staggerT <= 0) {
289:         this.state = 'chase';
290:         this.root.rotation.x = 0;
291:       }
292:       this.clampArena();
293:       return;
294:     }
295: 
296:     // chase / attack
297:     this.group.position.y = 0;
298:     this.attackCooldown -= dt;
299: 
300:     const dx = player.group.position.x - this.group.position.x;
301:     const dz = player.group.position.z - this.group.position.z;
302:     const dist = Math.hypot(dx, dz) || 0.001;
303:     const nx = dx / dist;
304:     const nz = dz / dist;
305: 
306:     // face player
307:     const targetYaw = Math.atan2(nx, nz);
308:     this.group.rotation.y = angleLerp(this.group.rotation.y, targetYaw, dt * 7);
309: 
310:     if (this.attackWindup > 0) {
311:       this.attackWindup -= dt;
312:       this.root.rotation.x = -0.12;
313:       const t = 1 - clamp(this.attackWindup / this.attackWindupDuration, 0, 1);
314:       this.armR.rotation.x = lerp(-0.2, -2.5, Math.min(1, t * 1.6));
315:       this.armR.rotation.z = lerp(0, 0.35, t);
316:       this.armL.rotation.x = lerp(0, 0.5, t);
317:       if (this.attackWindup <= 0) {
318:         this.armR.rotation.x = 0.55;
319:         this.armR.rotation.z = -0.1;
320:         this.attackCooldown = rand(...this.stats.cooldown);
321:         if (dist < this.stats.attackRange && player.alive) {
322:           player.takeDamage(this.stats.damage, this);
323:           game.onPlayerHurt(this);
324:           this.fx.bloodBurst(player.group.position.clone().setY(1.05), new THREE.Vector3(nx, 0.2, nz), 8, 0.8);
325:         }
326:         this.fx.slash(this.group.position.clone().setY(0.9), this.group.rotation.y, 0xff5a3d);
327:       }
328:       this.animateWalk(dt, 0);
329:       return;
330:     }
331: 
332:     if (!player.alive) {
333:       this.animateWalk(dt, 0);
334:       this.root.position.y = Math.sin(game.time * 1.5 + this.walkPhase) * 0.01;
335:       return;
336:     }
337: 
338:     if (dist > this.stats.attackStartRange) {
339:       const speed = this.health < this.maxHealth * 0.4 ? this.stats.injuredSpeed : this.stats.speed;
340:       let sx = nx * speed;
341:       let sz = nz * speed;
342: 
343:       // separation
344:       for (const other of game.npcs) {
345:         if (other === this || !other.alive) continue;
346:         const ox = this.group.position.x - other.group.position.x;
347:         const oz = this.group.position.z - other.group.position.z;
348:         const od = Math.hypot(ox, oz);
349:         if (od < 0.62 && od > 0.0001) {
350:           sx += (ox / od) * (0.62 - od) * 4;
351:           sz += (oz / od) * (0.62 - od) * 4;
352:         }
353:       }
354: 
355:       this.group.position.x += sx * dt;
356:       this.group.position.z += sz * dt;
357:       this.animateWalk(dt, 1);
358:     } else {
359:       this.animateWalk(dt, 0.25);
360:       if (this.attackCooldown <= 0) {
361:         this.attackWindup = this.stats.windup;
362:         this.attackWindupDuration = this.stats.windup;
363:         this.audio.swing();
364:       }
365:     }
366: 
367:     this.clampArena();
368:   }
