370:   updateThrown(dt, game) {
371:     this.throwT += dt;
372:     this.vel.y -= 17 * dt;
373:     this.group.position.addScaledVector(this.vel, dt);
374:     this.root.rotation.x += this.spin.x * dt;
375:     this.root.rotation.y += this.spin.y * dt;
376:     this.root.rotation.z += this.spin.z * dt;
377: 
378:     // hit other NPCs while flying
379:     for (const other of game.npcs) {
380:       if (other === this || !other.alive || other.state === 'grabbed') continue;
381:       const d = other.group.position.distanceTo(this.group.position);
382:       if (d < 0.62) {
383:         const dir = this.vel.clone().normalize();
384:         game.hitNPC(other, 16, dir, { thrownBody: true });
385:         this.vel.multiplyScalar(0.35);
386:         game.shake(0.14);
387:         break;
388:       }
389:     }
390: 
391:     const p = this.group.position;
392:     if (p.y < 0.35) {
393:       p.y = 0.35;
394:       if (Math.abs(this.vel.y) > 1.6) {
395:         this.vel.y *= -0.32;
396:         this.vel.x *= 0.6;
397:         this.vel.z *= 0.6;
398:         this.spin.multiplyScalar(0.65);
399:         this.fx.bloodBurst(p, new THREE.Vector3(0, 1, 0), 7, 0.7);
400:         game.shake(0.08);
401:       } else {
402:         this.group.position.y = 0;
403:         this.root.rotation.set(0, this.root.rotation.y, 0);
404:         this.fx.bloodPool(p, 0.7);
405:         this.state = 'stagger';
406:         this.staggerT = 0.65;
407:         this.takeDamage(14, new THREE.Vector3(0, 0, 0), { fall: true, silent: false });
408:         if (this.state !== 'dead') {
409:           this.audio.hurt();
410:         }
411:       }
412:     }
413: 
414:     this.clampArena(true);
415:   }
416: 
417:   animateWalk(dt, amount) {
418:     if (amount > 0) this.walkPhase += dt * (6 + amount * 5) * this.stats.gait;
419:     const swing = Math.sin(this.walkPhase) * 0.55 * amount;
420:     const swing2 = Math.sin(this.walkPhase + Math.PI) * 0.55 * amount;
421:     if (this.attackWindup <= 0) {
422:       this.armL.rotation.x = lerp(this.armL.rotation.x, swing, dt * 12);
423:       this.armR.rotation.x = lerp(this.armR.rotation.x, swing2, dt * 12);
424:       this.armL.rotation.z = 0.08;
425:       this.armR.rotation.z = -0.08;
426:     }
427:     this.legL.rotation.x = lerp(this.legL.rotation.x, -swing, dt * 14);
428:     this.legR.rotation.x = lerp(this.legR.rotation.x, -swing2, dt * 14);
429:     this.head.rotation.z = Math.sin(this.walkPhase * 0.5) * 0.06;
430:     this.head.rotation.x = Math.sin(this.walkPhase * 0.33) * 0.04;
431:     this.root.position.y = Math.abs(Math.sin(this.walkPhase)) * 0.025 * amount;
432:   }
433: 
434:   animateGrabbed(dt) {
435:     const t = this.grabT;
436:     this.armL.rotation.x = -1.6 + Math.sin(t * 11) * 0.7;
437:     this.armR.rotation.x = -1.5 + Math.cos(t * 10) * 0.7;
438:     this.armL.rotation.z = 0.6 + Math.sin(t * 8) * 0.2;
439:     this.armR.rotation.z = -0.6 - Math.cos(t * 8) * 0.2;
440:     this.legL.rotation.x = Math.sin(t * 12) * 0.8;
441:     this.legR.rotation.x = -Math.sin(t * 12) * 0.8;
442:     this.head.rotation.z = Math.sin(t * 6) * 0.2;
443:   }
444: 
445:   updateDeath(dt) {
446:     this.deathT += dt;
447:     const t = Math.min(1, this.deathT / 0.42);
448:     this.root.rotation.x = lerp(0, -Math.PI / 2, easeOut(t));
449:     this.root.position.y = lerp(0, 0.17, t);
450:     if (this.deathT > 2.2) {
451:       const fade = clamp(1 - (this.deathT - 2.2) / 1.2, 0, 1);
452:       for (const m of this.materials) {
453:         m.transparent = true;
454:         m.opacity = fade;
455:       }
456:       this.group.position.y = -0.1 * (1 - fade);
457:     }
458:     if (this.deathT > 3.5) {
459:       this.removed = true;
460:       this.dispose();
461:     }
462:   }
463: 
464:   clampArena(thrown = false) {
465:     const lim = this.bounds;
466:     const p = this.group.position;
467:     if (p.x > lim) { p.x = lim; if (thrown) this.vel.x *= -0.4; }
468:     if (p.x < -lim) { p.x = -lim; if (thrown) this.vel.x *= -0.4; }
469:     if (p.z > lim) { p.z = lim; if (thrown) this.vel.z *= -0.4; }
470:     if (p.z < -lim) { p.z = -lim; if (thrown) this.vel.z *= -0.4; }
471:   }
472: 
473:   takeDamage(amount, dir, opts = {}) {
474:     if (this.state === 'dead') return;
475:     this.health -= amount;
476:     this.flash = 0.13;
477:     this.hitCount++;
