302: /* ---------- touch ---------- */
303: .touch-ui { display: none; }
304: body.touch.playing .touch-ui { display: block; }
305: .stick {
306:   position: absolute;
307:   left: calc(18px + env(safe-area-inset-left));
308:   bottom: calc(128px + env(safe-area-inset-bottom));
309:   width: 112px; height: 112px;
310:   border: 1px solid rgba(236,228,212,0.2);
311:   border-radius: 50%;
312:   background: radial-gradient(circle, rgba(255,255,255,0.05), rgba(0,0,0,0.25));
313:   pointer-events: auto;
314:   touch-action: none;
315: }
316: .stick-knob {
317:   position: absolute; left: 50%; top: 50%;
318:   width: 46px; height: 46px; margin: -23px 0 0 -23px;
319:   border-radius: 50%;
320:   background: rgba(236,228,212,0.22);
321:   border: 1px solid rgba(236,228,212,0.45);
322:   box-shadow: 0 0 18px rgba(0,0,0,0.5);
323: }
324: .touch-actions {
325:   position: absolute;
326:   right: calc(16px + env(safe-area-inset-right));
327:   bottom: calc(110px + env(safe-area-inset-bottom));
328:   display: grid;
329:   grid-template-columns: 62px 62px;
330:   gap: 8px;
331:   pointer-events: auto;
332: }
333: .tbtn {
334:   pointer-events: auto;
335:   border: 1px solid rgba(236,228,212,0.25);
336:   background: rgba(10,10,12,0.66);
337:   color: var(--bone);
338:   font-family: var(--font-ui);
339:   font-size: 9px;
340:   font-weight: 700;
341:   letter-spacing: 0.12em;
342:   border-radius: 50%;
343:   width: 62px; height: 62px;
344:   display: grid;
345:   place-items: center;
346:   align-content: center;
347:   gap: 1px;
348:   touch-action: none;
349:   backdrop-filter: blur(4px);
350: }
351: .tbtn span { font-size: 8px; opacity: 0.5; letter-spacing: 0.08em; }
352: .tbtn:active { background: rgba(224,37,37,0.35); transform: scale(0.94); }
353: .tbtn-attack {
354:   width: 74px; height: 74px;
355:   border-color: rgba(224,37,37,0.7);
356:   background: radial-gradient(circle at 50% 40%, rgba(224,37,37,0.4), rgba(40,8,10,0.7));
357:   font-family: var(--font-display);
358:   font-size: 18px;
359:   letter-spacing: 0.04em;
360: }
361: .tbtn-attack span { font-family: var(--font-ui); font-size: 8px; }
362: .tbtn-small { width: 56px; height: 56px; }
363: .touch-actions { grid-template-columns: 56px 56px; align-items: end; }
364: .touch-actions .tbtn-attack { grid-column: 2; grid-row: 2; justify-self: end; }
