366: /* ---------- start / death ---------- */
367: .start, .death {
368:   position: absolute;
369:   inset: 0;
370:   z-index: 20;
371:   display: grid;
372:   place-items: center;
373:   padding: 24px;
374:   background:
375:     radial-gradient(ellipse at 50% 40%, rgba(30,10,10,0.35), rgba(4,4,6,0.86) 62%, #050506 100%);
376:   backdrop-filter: blur(2px);
377:   transition: opacity 0.45s ease, visibility 0.45s;
