419: .start-specs div { display: flex; flex-direction: column; gap: 3px; }
420: .start-specs b { font-family: var(--font-display); font-weight: 400; font-size: 30px; line-height: 1; color: var(--bone); }
421: .start-specs span { font-size: 8px; letter-spacing: 0.24em; color: rgba(236,228,212,0.42); font-weight: 700; }
422: .start-btn {
423:   pointer-events: auto;
424:   font-family: var(--font-display);
425:   font-size: 26px;
426:   letter-spacing: 0.1em;
